3class Board {
4
5
6    // count variable
7    int count = 0;
8
9    String board[] = { " ", " ", " ", " ", " ", " ", " ", " ", " " };
10
11    void printBoard() {
12
13        System.out.println(" " + board[0] + " | " + board[1] + " | " + board[2]);
14        System.out.println("-----------");
15        System.out.println(" " + board[3] + " | " + board[4] + " | " + board[5]);
16        System.out.println("-----------");
17        System.out.println(" " + board[6] + " | " + board[7] + " | " + board[8]);
18
19    }
20
21    boolean updateBoard(int position, String type) {
22
23        // if a player selects position n, n-1 index should be updated
24        // if the position is not already filled, update the board
25        if (board[position - 1] == " ") {
26            board[position - 1] = type;
27
28
29            // increase the value of count by 1
30            count++;
31
32            return true;
33        }
34
35        // if the position is already filled, ask user to select another position
36        else {
37            System.out.println("Position already selected. Select another position.");
38            return false;
39
40        }
41    }
42
43
44    // if all fields are selected and there is no winner, it's draw
45    // returning true if it's draw
46    boolean checkDraw() {
47
48        // check if count == 9
49        if (count == 9) {
50            return true;
51        } 
52        else {
53            return false;
54        }
55    }
56
57    // if three symbols appears in a row, returning True
58    boolean checkWinner(String type) {
59        if ((board[0] == type && board[1] == type && board[2] == type)
60                || (board[3] == type && board[4] == type && board[5] == type)
61                || (board[6] == type && board[7] == type && board[8] == type)
62                || (board[0] == type && board[3] == type && board[6] == type)
63                || (board[1] == type && board[4] == type && board[7] == type)
64                || (board[2] == type && board[5] == type && board[8] == type)
65                || (board[0] == type && board[4] == type && board[8] == type)
66                || (board[2] == type && board[4] == type && board[6] == type)) {
67            return true;
68        }
69
70        else {
71            return false;
72        }
73
74    }
