99class Game {
100
101    Board board = new Board();
102    Player player1 = new Player("X");
103    Player player2 = new Player("O");
104
105    Player currentPlayer = player1;
106
107    void play() {
108        // using an infinite loop to run the game
109        // we will later add conditions to terminate the loop
110        String message = "enter the position (1 - 9):";
111        while (true) {
112
113            message = "enter the position (1 - 9):";
114            System.out.println(currentPlayer.name + " " + message);
115            Scanner input = new Scanner(System.in);
116            int position = input.nextInt();
117
118            // the updateBoard() method return true if
119            // the user selected position is not already filled
120            if (board.updateBoard(position, currentPlayer.type)) {
121
122                board.printBoard();
123
124                // changing current player when board is updated
125                if (currentPlayer == player1) {
126                    currentPlayer = player2;
127                }
128
129                else {
130                    currentPlayer = player1;
131
132                }
133            }
134        }
135    }
136}
